def render_taxonomy(label_map):

    rgb = np.zeros(
        (
            label_map.shape[0],
            label_map.shape[1],
            3
        ),
        dtype=np.uint8
    )

    for class_id, color in PALETTE.items():

        rgb[
            label_map == class_id
        ] = color

    return rgb


