# ===== cell 6 ====================================================
import torch.nn.functional as F

from transformers import (
    SegformerImageProcessor,
    SegformerForSemanticSegmentation
)

ADE_MODEL_ID = (
    "nvidia/segformer-b5-finetuned-ade-640-640"
)

print("Loading ADE20K...")

ade_processor = (
    SegformerImageProcessor
    .from_pretrained(
        ADE_MODEL_ID
    )
)

ade_model = (
    SegformerForSemanticSegmentation
    .from_pretrained(
        ADE_MODEL_ID
    )
    .to(device)
)

ade_model.eval()

print("✓ ADE loaded")

@torch.no_grad()
def run_ade(image):

    W, H = image.size

    inputs = ade_processor(
        images=image,
        return_tensors="pt"
    )

    inputs = {
        k: v.to(device)
        for k, v in inputs.items()
    }

    outputs = ade_model(**inputs)

    logits = F.interpolate(
        outputs.logits,
        size=(H, W),
        mode="bilinear",
        align_corners=False
    )

    probs = torch.softmax(
        logits,
        dim=1
    )

    confidence, prediction = probs.max(
        dim=1
    )

    return (
        prediction[0]
        .cpu()
        .numpy()
        .astype(np.int32),

        confidence[0]
        .cpu()
        .numpy()
        .astype(np.float32)
    )


ade_pred, ade_confidence = run_ade(
    image
)

ADE_ID2LABEL = {
    int(k): str(v).lower()
    for k, v
    in ade_model.config.id2label.items()
}

print("✓ ADE inference complete")

def ade_ids_fuzzy(
    include_terms,
    exclude_terms=None
):

    if exclude_terms is None:
        exclude_terms = []

    found = []

    for class_id, name in ADE_ID2LABEL.items():

        included = any(
            term.lower() in name
            for term in include_terms
        )

        excluded = any(
            term.lower() in name
            for term in exclude_terms
        )

        if included and not excluded:
            found.append(class_id)

    return found


def ade_mask_fuzzy(
    include_terms,
    exclude_terms=None
):

    ids = ade_ids_fuzzy(
        include_terms,
        exclude_terms
    )

    if not ids:

        return np.zeros(
            (H, W),
            dtype=bool
        )

    return np.isin(
        ade_pred,
        ids
    )


ADE_GLASS_V2 = ade_mask_fuzzy([
    "window",
    "glass"
])

ADE_ROAD_V2 = ade_mask_fuzzy([
    "road"
])

ADE_SIDEWALK_V2 = ade_mask_fuzzy([
    "sidewalk",
    "path"
])

ADE_BUILDING_V2 = ade_mask_fuzzy([
    "building",
    "house",
    "skyscraper"
])

ADE_SKY_V2 = ade_mask_fuzzy([
    "sky"
])

ADE_TREE_V2 = ade_mask_fuzzy([
    "tree"
])

ADE_PLANT_V2 = ade_mask_fuzzy([
    "plant",
    "grass",
    "flower"
])

ADE_FENCE_V3 = ade_mask_fuzzy([
    "fence",
    "railing"
])


print("ADE glass:", int(ADE_GLASS_V2.sum()))
