from transformers import (
    AutoImageProcessor,
    Mask2FormerForUniversalSegmentation
)

MAPILLARY_MODEL_ID = (
    "facebook/"
    "mask2former-swin-large-"
    "mapillary-vistas-semantic"
)

print("Loading Mapillary...")

map_processor = (
    AutoImageProcessor
    .from_pretrained(
        MAPILLARY_MODEL_ID
    )
)

map_model = (
    Mask2FormerForUniversalSegmentation
    .from_pretrained(
        MAPILLARY_MODEL_ID
    )
    .to(device)
)

map_model.eval()

print("✓ Mapillary loaded")

inputs = map_processor(
    images=image,
    return_tensors="pt"
)

inputs = {
    k: v.to(device)
    for k, v in inputs.items()
}

with torch.no_grad():

    outputs = map_model(
        **inputs
    )


map_pred = (
    map_processor
    .post_process_semantic_segmentation(
        outputs,
        target_sizes=[
            (H, W)
        ]
    )[0]
    .cpu()
    .numpy()
    .astype(np.int32)
)


MAP_ID2LABEL = {
    int(k): str(v).lower()
    for k, v
    in map_model.config.id2label.items()
}

print("✓ Mapillary inference complete")

def mapillary_ids(
    include_terms,
    exclude_terms=None
):

    if exclude_terms is None:
        exclude_terms = []

    found = []

    for class_id, name in MAP_ID2LABEL.items():

        included = any(
            term.lower() in name
            for term in include_terms
        )

        excluded = any(
            term.lower() in name
            for term in exclude_terms
        )

        if included and not excluded:
            found.append(class_id)

    return found


def mapillary_mask(
    include_terms,
    exclude_terms=None
):

    ids = mapillary_ids(
        include_terms,
        exclude_terms
    )

    if not ids:

        return np.zeros(
            (H, W),
            dtype=bool
        )

    return np.isin(
        map_pred,
        ids
    )


