@torch.no_grad()
def detect_one_class(
    source_image,
    class_name,
    offset_x=0,
    offset_y=0
):

    phrases = AUTO_LABEL_QUERIES[
        class_name
    ]

    inputs = grounding_processor(
        images=source_image,
        text=[phrases],
        return_tensors="pt"
    ).to(device)

    outputs = grounding_model(
        **inputs
    )

    results = (
        grounding_processor
        .post_process_grounded_object_detection(
            outputs,
            inputs.input_ids,
            threshold=CLASS_THRESHOLDS[
                class_name
            ],
            text_threshold=0.18,
            target_sizes=[
                (
                    source_image.height,
                    source_image.width
                )
            ]
        )
    )[0]

    detections = []

    for box, score in zip(
        results["boxes"],
        results["scores"]
    ):

        x1, y1, x2, y2 = (
            box.detach()
            .cpu()
            .tolist()
        )

        detections.append({

            "class_name":
                class_name,

            "class_id":
                LABEL2ID[
                    class_name
                ],

            "score":
                float(
                    score.detach()
                    .cpu()
                    .item()
                ),

            "box": [
                x1 + offset_x,
                y1 + offset_y,
                x2 + offset_x,
                y2 + offset_y
            ]
        })

    return detections

