from torchvision.ops import nms


def nms_group(
    detections,
    key_name,
    iou=0.42
):

    if not detections:
        return []

    result = []

    groups = sorted(
        set(
            d[key_name]
            for d in detections
        )
    )

    for group in groups:

        subset = [
            d
            for d in detections
            if d[key_name] == group
        ]

        boxes = torch.tensor(
            [
                d["box"]
                for d in subset
            ],
            dtype=torch.float32
        )

        scores = torch.tensor(
            [
                d["score"]
                for d in subset
            ],
            dtype=torch.float32
        )

        keep = nms(
            boxes,
            scores,
            iou
        )

        result.extend(
            subset[i]
            for i in keep.tolist()
        )

    return result


