@torch.no_grad()
def boxes_to_masks(
    image,
    detections
):

    if not detections:
        return []

    boxes = [
        d["box"]
        for d in detections
    ]

    inputs = (
        sam_processor(
            images=image,
            input_boxes=[boxes],
            return_tensors="pt"
        )
        .to(device)
    )

    outputs = sam_model(
        **inputs,
        multimask_output=False
    )

    masks = (
        sam_processor
        .post_process_masks(
            outputs.pred_masks.cpu(),
            inputs["original_sizes"]
        )[0]
    )

    output = []

    for i, det in enumerate(
        detections
    ):

        mask = masks[i]

        while mask.ndim > 2:
            mask = mask[0]

        output.append({
            **det,
            "mask":
                mask.numpy() > 0
        })

    return output

