def mask_geometry(mask):

    ys, xs = np.where(mask)

    if len(xs) == 0:

        return {
            "area_ratio": 0,
            "cx": 0,
            "cy": 0
        }

    return {

        "area_ratio":
            float(mask.mean()),

        "cx":
            float(xs.mean() / W),

        "cy":
            float(ys.mean() / H)
    }


