def shift_mask(mask, dy=0, dx=0):

    out = np.zeros_like(
        mask,
        dtype=bool
    )

    y0 = max(0, -dy)
    y1 = mask.shape[0] - max(0, dy)

    x0 = max(0, -dx)
    x1 = mask.shape[1] - max(0, dx)

    yd0 = max(0, dy)
    xd0 = max(0, dx)

    if y1 > y0 and x1 > x0:

        out[
            yd0:yd0 + (y1-y0),
            xd0:xd0 + (x1-x0)
        ] = mask[
            y0:y1,
            x0:x1
        ]

    return out


